<?php
namespace App\Domain\Products;use App\Domain\PublicChrome\PublicAssetPath;use App\Models\{Product,ProductCategory};use Illuminate\Support\Facades\Cache;use Throwable;final class ProductIndexViewData {public function get(?string $category,int $page):array{try{return Cache::remember('public.products.index.v1.'.ProductCache::indexVersion().'.'.($category?:'all').'.'.$page,now()->addMinutes(10),fn()=>$this->load($category,$page));}catch(Throwable){return $this->load($category,$page);}}private function load(?string $category,int $page):array{$cat=$category?ProductCategory::where('slug',$category)->where('is_active',true)->first():null;if($category&&!$cat)return ['invalid'=>true,'items'=>[],'categories'=>[],'pagination'=>[]];$p=Product::publiclyVisible()->with('category')->when($cat,fn($q)=>$q->whereBelongsTo($cat))->orderByDesc('is_featured')->orderBy('display_order')->paginate(12,['*'],'page',$page);return ['invalid'=>false,'categories'=>ProductCategory::where('is_active',true)->orderBy('display_order')->limit(50)->get()->map(fn($c)=>['name'=>$c->name,'slug'=>$c->slug])->all(),'items'=>$p->getCollection()->map(fn($x)=>['title'=>$x->title,'slug'=>$x->slug,'description'=>$x->short_description,'featured'=>(bool)$x->is_featured,'image'=>PublicAssetPath::isSafe($x->featured_image_path)?$x->featured_image_path:null,'image_alt'=>$x->featured_image_alt,'category'=>$x->category?->name,'url'=>route('products.show',$x->slug)])->all(),'pagination'=>['current'=>$p->currentPage(),'last'=>$p->lastPage(),'previous'=>$p->previousPageUrl(),'next'=>$p->nextPageUrl(),'total'=>$p->total()]];}}